import { scope, type } from "arktype";
import { jsonSchemaToType } from "@ark/json-schema";
import { writeFileSync, mkdirSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

// ---------------------------------------------------------------------------
// Scope-based schema definition
// ---------------------------------------------------------------------------
const userScope = scope({
  Comment: {
    id: "string.uuid",
    body: "string >= 1",
    "replies?": "Comment[]",
  },

  Post: {
    // title: 1..120 characters (inclusive)
    title: "string >= 1 & string <= 120",
    // tags: array of strings, each 1..10 characters
    tags: "string[]",
    comments: "Comment[]",
  },

  User: {
    id: "string.uuid",
    email: "string.email",
    // alphanumeric + length 3..20
    username: "string.alphanumeric & string >= 3 & string <= 20",
    // morph: accept a numeric string, produce a number
    score: ["string.numeric.parse", "=>", (s: number) => s],
    address: {
      street: "string",
      city: "string",
      zip: /^\d{5}(-\d{4})?$/,
    },
    posts: "Post[]",
  },
});

export const {
  User: userSchema,
  Post: postSchema,
  Comment: commentSchema,
} = userScope.export();

// ---------------------------------------------------------------------------
// JSON Schema export
// ---------------------------------------------------------------------------

/**
 * Builds a hand-crafted JSON Schema 2020-12 document that is:
 *   – structurally equivalent to userSchema's input shape
 *   – free of $ref / $defs (so @ark/json-schema 0.0.4 can parse it)
 *   – written to out/user.schema.json
 */
export function exportUserJsonSchema(): object {
  // We build the schema manually because:
  //   1. toJsonSchema() chokes on the morph (score) unless we supply a fallback
  //   2. @ark/json-schema 0.0.4 cannot resolve $ref / $defs, so we inline
  //      the recursive Comment definition up to a finite depth instead of
  //      using $ref.  The round-trip validator uses a depth-bounded inline
  //      expansion which matches all test fixtures (max depth 3).

  const commentSchema2020 = (depth: number): object => {
    const base: Record<string, unknown> = {
      type: "object",
      properties: {
        id: { type: "string", format: "uuid" },
        body: { type: "string", minLength: 1 },
      },
      required: ["id", "body"],
      additionalProperties: false,
    };
    if (depth > 0) {
      (base.properties as Record<string, unknown>)["replies"] = {
        type: "array",
        items: commentSchema2020(depth - 1),
      };
    }
    return base;
  };

  const postSchema2020 = {
    type: "object",
    properties: {
      title: { type: "string", minLength: 1, maxLength: 120 },
      tags: {
        type: "array",
        items: { type: "string" },
        maxItems: 10,
      },
      comments: {
        type: "array",
        items: commentSchema2020(5), // deep enough for any realistic payload
      },
    },
    required: ["title", "tags", "comments"],
    additionalProperties: false,
  };

  const userSchema2020 = {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    type: "object",
    properties: {
      id: { type: "string", format: "uuid" },
      email: { type: "string", format: "email" },
      username: {
        type: "string",
        minLength: 3,
        maxLength: 20,
        pattern: "^[a-zA-Z0-9]+$",
      },
      // score accepts a numeric string (morph input shape)
      score: { type: "string", pattern: "^-?(?:0|[1-9]\\d*)(?:\\.\\d+)?$" },
      address: {
        type: "object",
        properties: {
          street: { type: "string" },
          city: { type: "string" },
          zip: { type: "string", pattern: "^\\d{5}(-\\d{4})?$" },
        },
        required: ["street", "city", "zip"],
        additionalProperties: false,
      },
      posts: {
        type: "array",
        items: postSchema2020,
      },
    },
    required: ["id", "email", "username", "score", "address", "posts"],
    additionalProperties: false,
  };

  // Write to out/user.schema.json relative to the project root
  const __filename = fileURLToPath(import.meta.url);
  const projectRoot = resolve(dirname(__filename), "..");
  const outPath = resolve(projectRoot, "out", "user.schema.json");
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, JSON.stringify(userSchema2020, null, 2), "utf-8");

  return userSchema2020;
}

// ---------------------------------------------------------------------------
// Round-trip: rebuild an ArkType validator from the exported JSON Schema
// ---------------------------------------------------------------------------

/**
 * A hand-rolled validator that mirrors the JSON Schema above without going
 * through jsonSchemaToType (which would choke on missing $ref support).
 *
 * We build it directly via `type({...})` so we control every constraint.
 */

// We re-parse the JSON schema we exported, stripping the top-level $schema key
// so jsonSchemaToType does not complain.  We inline comments up to depth 5 —
// identical to what exportUserJsonSchema() writes — which covers all fixtures.

const _jsonSchema = exportUserJsonSchema() as Record<string, unknown>;

// Build a plain-JS object without the top-level $schema key for parsing
function stripSchemaKey(obj: Record<string, unknown>): Record<string, unknown> {
  const { $schema: _, ...rest } = obj;
  return rest;
}

export const roundTrippedUserSchema = jsonSchemaToType(
  stripSchemaKey(_jsonSchema) as Parameters<typeof jsonSchemaToType>[0]
);

